  1	/**
  2	 * One audit row per domain event; day grouping.
  3	 *
  4	 * Owner C implements `@/server/services/activity-service`, which subscribes to
  5	 * the event bus at module init.
  6	 */
  7	import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";
  8	
  9	vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
 10	vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
 11	vi.mock("@/server/repositories/activity-repository", async (importOriginal) => {
 12	  const actual =
 13	    await importOriginal<typeof import("@/server/repositories/activity-repository")>();
 14	  return { ...actual, insertActivity: vi.fn(actual.insertActivity) };
 15	});
 16	
 17	import { emit, subscribe, subscriberCount } from "@/lib/event-bus";
 18	import { PermissionDeniedError } from "@/lib/permissions";
 19	import { TenantScopeError } from "@/lib/tenant";
 20	import * as activityRepo from "@/server/repositories/activity-repository";
 21	import {
 22	  exportActivity,
 23	  groupByDay,
 24	  listActivity,
 25	  registerActivityListeners,
 26	} from "@/server/services/activity-service";
 27	import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
 28	import type { Tenant } from "../server/_support/fixtures";
 29	import type { ActivityEvent } from "@/types/activity";
 30	import type { CommentId, IssueId } from "@/types/common";
 31	import type { Unsubscribe } from "@/types/event";
 32	
 33	let cleanup: () => void;
 34	let tenant: Tenant;
 35	let detach: Unsubscribe;
 36	
 37	beforeAll(async () => {
 38	  cleanup = await useTemporaryDatabase();
 39	  tenant = await createTenant("activity", "growth");
 40	  detach = registerActivityListeners();
 41	});
 42	
 43	afterAll(() => {
 44	  detach();
 45	  cleanup();
 46	});
 47	
 48	afterEach(() => {
 49	  vi.mocked(activityRepo.insertActivity).mockClear();
 50	});
 51	
 52	describe("services/activity-service", () => {
 53	  // subscribe() is registered for each ActivityAction-shaped event type.
 54	  it("subscribes to every event that maps to an ActivityAction", () => {
 55	    const before = subscriberCount("project.created");
 56	    const off = registerActivityListeners();
 57	
 58	    // registerActivityListeners() is idempotent per call — each call attaches
 59	    // its own listener set, so calling it a second time adds one more.
 60	    expect(subscriberCount("project.created")).toBe(before + 1);
 61	    expect(subscriberCount("issue.created")).toBeGreaterThanOrEqual(1);
 62	    expect(subscriberCount("member.role_changed")).toBeGreaterThanOrEqual(1);
 63	    expect(subscriberCount("billing.plan_changed")).toBeGreaterThanOrEqual(1);
 64	
 65	    off();
 66	    expect(subscriberCount("project.created")).toBe(before);
 67	  });
 68	
 69	  // One emit produces exactly one activity row, with the actor and subject.
 70	  it("records one audit row per emitted event", async () => {
 71	    await emit("project.created", {
 72	      orgId: tenant.org.id,
 73	      actorId: tenant.userIds.member,
 74	      occurredAt: tenant.org.createdAt,
 75	      projectId: tenant.project.id,
 76	      name: "Audited project",
 77	      slug: "audited-project",
 78	    });
 79	
 80	    const page = await listActivity(tenant.actors.member, {
 81	      orgId: tenant.org.id,
 82	      action: ["project.created"],
 83	      limit: 25,
 84	      cursor: null,
 85	    });
 86	
 87	    expect(page.items).toHaveLength(1);
 88	    expect(page.items[0]).toMatchObject({
 89	      orgId: tenant.org.id,
 90	      action: "project.created",
 91	      actorId: tenant.userIds.member,
 92	      subjectKind: "project",
 93	      subjectId: tenant.project.id,
 94	    });
 95	  });
 96	
 97	  // A second identical emit produces a second row — the log is append-only.
 98	  it("appends rather than de-duplicates repeated events", async () => {
 99	    const payload = {
100	      orgId: tenant.org.id,
101	      actorId: tenant.userIds.member,
102	      occurredAt: tenant.org.createdAt,
103	      projectId: tenant.project.id,
104	      name: "Repeat project",
105	      slug: "repeat-project",
106	    } as const;
107	
108	    const before = await listActivity(tenant.actors.member, {
109	      orgId: tenant.org.id,
110	      action: ["project.created"],
111	      limit: 100,
112	      cursor: null,
113	    });
114	
115	    await emit("project.created", payload);
116	    await emit("project.created", payload);
117	
118	    const after = await listActivity(tenant.actors.member, {
119	      orgId: tenant.org.id,
120	      action: ["project.created"],
121	      limit: 100,
122	      cursor: null,
123	    });
124	
125	    expect(after.total).toBe(before.total + 2);
126	  });
127	
128	  // A throwing repository must not fail the emit for sibling subscribers.
129	  it("isolates a write failure from the emitting service", async () => {
130	    vi.mocked(activityRepo.insertActivity).mockRejectedValueOnce(
131	      new Error("activity store unavailable"),
132	    );
133	
134	    const sibling = vi.fn();
135	    const offSibling = subscribe("comment.created", sibling);
136	
137	    await expect(
138	      emit("comment.created", {
139	        orgId: tenant.org.id,
140	        actorId: tenant.userIds.member,
141	        occurredAt: tenant.org.createdAt,
142	        commentId: "cmt-isolation" as CommentId,
143	        issueId: "issue-isolation" as IssueId,
144	        mentionedUserIds: [],
145	      }),
146	    ).resolves.toBeUndefined();
147	
148	    expect(sibling).toHaveBeenCalledTimes(1);
149	    offSibling();
150	  });
151	
152	  // groupByDay buckets rows into ActivityGroup entries keyed by calendar day.
153	  it("groups the feed into calendar days", () => {
154	    const orgId = tenant.org.id;
155	    const build = (id: string, day: string): ActivityEvent => ({
156	      id: id as ActivityEvent["id"],
157	      orgId,
158	      action: "issue.created",
159	      actorId: null,
160	      subjectKind: "issue",
161	      subjectId: "s1",
162	      projectId: null,
163	      summary: "Created issue",
164	      metadata: {},
165	      occurredAt: `${day}T10:00:00.000Z` as ActivityEvent["occurredAt"],
166	    });
167	
168	    const groups = groupByDay([
169	      build("e1", "2026-01-01"),
170	      build("e2", "2026-01-02"),
171	      build("e3", "2026-01-01"),
172	    ]);
173	
174	    expect(groups).toHaveLength(2);
175	    expect(groups[0]?.day).toBe("2026-01-02");
176	    expect(groups[0]?.events).toHaveLength(1);
177	    expect(groups[1]?.day).toBe("2026-01-01");
178	    expect(groups[1]?.events).toHaveLength(2);
179	  });
180	
181	  // Rows are scoped to the actor's org, and export needs activity:export.
182	  it("scopes the feed to the actor's organization", async () => {
183	    const other = await createTenant("activity-other", "growth");
184	
185	    await expect(
186	      listActivity(other.actors.owner, {
187	        orgId: tenant.org.id,
188	        limit: 25,
189	        cursor: null,
190	      }),
191	    ).rejects.toBeInstanceOf(TenantScopeError);
192	
193	    const own = await listActivity(tenant.actors.member, {
194	      orgId: tenant.org.id,
195	      limit: 25,
196	      cursor: null,
197	    });
198	    expect(own.total).toBeGreaterThanOrEqual(1);
199	
200	    // Exporting the audit log needs activity:export, which only admin+ holds.
201	    await expect(
202	      exportActivity(tenant.actors.member, {
203	        orgId: tenant.org.id,
204	        since: tenant.org.createdAt,
205	        until: tenant.org.createdAt,
206	        format: "json",
207	      }),
208	    ).rejects.toBeInstanceOf(PermissionDeniedError);
209	
210	    await expect(
211	      exportActivity(tenant.actors.admin, {
212	        orgId: tenant.org.id,
213	        since: tenant.org.createdAt,
214	        until: tenant.org.createdAt,
215	        format: "json",
216	      }),
217	    ).resolves.toEqual(expect.any(String));
218	  });
219	});

