}

input.new_string:
/**
 * Next per-project issue number. Archived issues keep their number, so the
 * max is taken over every row rather than the live ones. A project's
 * high-water mark is also tracked in `issue_number_counters`, since a number
 * must never be reissued even after the issue that carried it moves away to
 * another project — at that point it no longer shows up in `max(number)`
 * over this project's current rows.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const db = getDb();

  const rowMax = db
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();

  const counterPredicate = and(
    orgPredicate(issueNumberCounters.orgId, orgId),
    eq(issueNumberCounters.projectId, projectId),
  );
  const counter = db
    .select()
    .from(issueNumberCounters)
    .where(counterPredicate)
    .get();

  const next = Math.max(rowMax?.value ?? 0, counter?.highestNumber ?? 0) + 1;

  if (counter) {
    db.update(issueNumberCounters)
      .set({ highestNumber: next })
      .where(counterPredicate)
      .run();
  } else {
    db.insert(issueNumberCounters).values({ orgId, projectId, highestNumber: next }).run();
  }

  return next;
}

