 * `issueNumber` is expected to come from `nextIssueNumber(orgId, projectId)`
 * for the target project, exactly as a newly created issue's would.
 */
export async function relocateIssueToProject(
  orgId: OrgId,
  issueId: IssueId,
  projectId: ProjectId,
  issueNumber: number,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({
      projectId,
      number: issueNumber,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);
  return toIssue(row);
}

