/**
 * Moves an issue to another project of the same workspace (ADR 0011).
 *
 * Requires both `issue:update` on the issue and `issue:create` on the target
 * project — the same two gates editing the issue and creating one in the
 * target each need on their own — and the target's per-project issue quota
 * applies exactly as it does to creating an issue there. The issue keeps its
 * title, description, status, priority, assignee, estimate, due date,
 * labels, comments and attachments; only its project and number change. The
 * old number is never reissued in the source project. Moving an issue into
 * the project it is already in changes nothing and publishes no event.
 */
export async function moveIssueToProject(
  actor: Actor,
  input: MoveIssueToProjectInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  if (issue.projectId === input.toProjectId) {
    return issue;
  }

  const targetProject = requireFound(
    await projectRepo.findProjectById(input.orgId, input.toProjectId),
    "Project",
    input.toProjectId,
  );
  assertNotArchived("Project", targetProject.id, targetProject);
  assertCan(actor, "issue:create", projectResource(targetProject));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.toProjectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${targetProject.key}`,
    );
  }

  const fromProjectId = issue.projectId;
  const fromNumber = issue.number;
  const toNumber = await issueRepo.nextIssueNumber(
    input.orgId,
    input.toProjectId,
  );

  const after = await issueRepo.relocateIssueToProject(
    input.orgId,
    input.issueId,
    input.toProjectId,
    toNumber,
  );

  await emit("issue.moved", {
    ...actorEnvelope(actor),
    issueId: after.id,
    fromProjectId,
    toProjectId: input.toProjectId,
    fromNumber,
    toNumber,
  });

  return after;
}

