import { afterAll, beforeAll, describe, expect, it } from "vitest";

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as issueService from "@/server/services/issue-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("movescratch");
});

afterAll(() => {
  cleanup();
});

describe("scratch: moveIssueToProject", () => {
  it("renumbers into the target project and emits issue.moved", async () => {
    const other = await projectRepo.insertProject({
      orgId: tenant.org.id,
      name: "Other",
      slug: "other",
      key: "OTH",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#000000",
      targetDate: null,
    });

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Move me" }),
    );

    const seen: unknown[] = [];
    const off = subscribe("issue.moved", (p) => {
      seen.push(p);
    });

    const moved = await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: other.id,
    });

    off();

    expect(moved.projectId).toBe(other.id);
    expect(moved.number).toBe(1);
    expect(moved.title).toBe("Move me");
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      issueId: issue.id,
      fromProjectId: tenant.project.id,
      toProjectId: other.id,
      fromNumber: issue.number,
      toNumber: 1,
    });

    // same-project move is a no-op and publishes nothing
    const seen2: unknown[] = [];
    const off2 = subscribe("issue.moved", (p) => seen2.push(p));
    const unchanged = await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: other.id,
    });
    off2();
    expect(seen2).toHaveLength(0);
    expect(unchanged.number).toBe(1);

    // retired number: creating a new issue in the source project never reuses issue.number
    const replacement = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Replacement" }),
    );
    expect(replacement.number).toBeGreaterThan(issue.number);

    // moving back and forth still never reissues a number
    const movedBack = await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: tenant.project.id,
    });
